"use client";
import { useState } from "react";


export default function BookifyContact() {
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  return (
    <div style={styles.root}>
      <div style={styles.bgOverlay} />

      {/* NAVBAR */}
      <nav style={styles.nav}>
        <span style={styles.logo}>Bookify</span>
        <div style={styles.navCenter}>
          {["Home", "Event/Booking", "Blog", "Contact", "Profile"].map((l) => (
            <a key={l} href="#" style={{ ...styles.navLink, ...(l === "Contact" ? styles.navLinkActive : {}) }}>
              {l}
            </a>
          ))}
          <button style={styles.loginBtn}>LOG IN</button>
        </div>
      </nav>

      {/* PAGE BODY */}
      <div style={styles.pageBody}>

        {/* LEFT — info panel */}
        <div style={styles.infoPanel}>
          <p style={styles.infoEyebrow}>GET IN TOUCH</p>
          <h1 style={styles.infoTitle}>Contact Us</h1>
          <p style={styles.infoDesc}>
            Have questions about booking an event or need help with your account?
            Our team is here for you — reach out and we'll get back to you shortly.
          </p>

          <div style={styles.infoItems}>
            {[
              { icon: "📍", label: "Address",  value: "14 Event Plaza, Lagos, NG" },
              { icon: "📞", label: "Phone",    value: "+234 800 123 4567" },
              { icon: "✉️", label: "Email",    value: "hello@bookify.com" },
            ].map((item) => (
              <div key={item.label} style={styles.infoItem}>
                <span style={styles.infoItemIcon}>{item.icon}</span>
                <div>
                  <p style={styles.infoItemLabel}>{item.label}</p>
                  <p style={styles.infoItemValue}>{item.value}</p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* RIGHT — form card */}
        <div style={styles.card}>
          <p style={styles.cardSub}>ORGANIZER'S PAGE</p>
          <h2 style={styles.cardTitle}>SEND US A MESSAGE</h2>

          {[
            { name: "name",    placeholder: "Full Name",     type: "text",  icon: "👤" },
            { name: "email",   placeholder: "Email Address", type: "email", icon: "✉️" },
            { name: "subject", placeholder: "Subject",       type: "text",  icon: "📋" },
          ].map((field) => (
            <div key={field.name} style={styles.inputRow}>
              <span style={styles.inputIcon}>{field.icon}</span>
              <input
                style={styles.input}
                type={field.type}
                name={field.name}
                placeholder={field.placeholder}
                value={form[field.name as keyof typeof form]}
                onChange={handleChange}
              />
            </div>
          ))}

          <div style={styles.textareaRow}>
            <span style={{ ...styles.inputIcon, alignSelf: "flex-start", paddingTop: "12px" }}>💬</span>
            <textarea
              style={styles.textarea}
              name="message"
              placeholder="Your Message"
              value={form.message}
              onChange={handleChange}
              rows={5}
            />
          </div>

          <button style={styles.sendBtn}>SEND MESSAGE</button>

          <p style={styles.termsText}>
            By contacting us you agree to our{" "}
            <a href="#" style={styles.termsLink}>terms &amp; conditions</a>
          </p>
        </div>
      </div>
    </div>
  );
}

